// Picks the first row whose status is "pending".
// Works with the Google Sheets "Get row(s)" node in front of it.
// With no Sheet connected yet, it uses a TEST row so you can run the workflow end to end.
const rows = $input.all().map(i => i.json).filter(r => r && r.name);
const pending = rows.find(r => String(r.status || '').toLowerCase() === 'pending');
const row = pending || {
  name: 'Ismail al-Jazari', country: 'Upper Mesopotamia', era: '12th–13th century',
  invention: 'programmable automata, water clocks', wiki_title: 'Ismail_al-Jazari',
  status: 'pending', row_number: null, _test: true
};
if (!pending && rows.length) throw new Error('No row with status = pending left in the Sheet.');
return [{ json: row }];

const row = $('Pick Innovator').first().json;
const pages = Object.values(($json.query && $json.query.pages) || {});
const source = (pages[0] && pages[0].extract) || '';
if (source.length < 300) throw new Error('Wikipedia text missing or too short for wiki_title: ' + row.wiki_title);

const SYSTEM = "You write 30–40 second vertical "Forgotten Innovators" shorts for T&I NEWS. Audience: curious non-engineers worldwide.

RULES
1. Use ONLY facts present in the SOURCE TEXT. If a fact is not in it, leave it out. Hedge where the source hedges ("described", "earliest known").
2. Narration is plain spoken English, short sentences, no jargon. Total narration across all scenes: 75–95 words.
3. The first scene must hook in under 3 seconds (a surprising year, number or claim).
4. Use 6–8 scenes chosen from the SCENE MENU. Always start with "hook" and end with "outro". Use "globe" once.
5. Output ONLY valid JSON matching the OUTPUT SHAPE. No markdown, no commentary.

SCENE MENU (fields per type; every scene also needs "durationSec" (4–8) and "narration")
- hook: kicker (≤4 words), headline (≤6 words, ends just before the payoff word), highlight (1–2 words, the payoff)
- globe: lat, lon (decimal degrees of where they worked), place (city), sub (court/institution · region, ≤40 chars)
- counter: to (a year or number from the source), label (≤60 chars), sub (≤30 chars)
- iconGrid: count (10–60, a real number from the source), icon (gear|clock|drum|engine|robot|book|drop|bulb), label (≤22 chars), value (≤55 chars)
- machine: title (≤32 chars), steps (exactly 4 items, each ≤28 chars, explaining how the invention works)
- legacy: title ("Then → Now"), items (exactly 3: {icon, then (≤26 chars), now (≤16 chars)})
- outro: name, years, cta ("Follow for more forgotten innovators")

OUTPUT SHAPE
{
  "brand": {"name": "T&I NEWS", "url": "tai.news", "bg": "#0A1630", "accent": "#D4A63A", "text": "#F4E9D0"},
  "sfx": true,
  "scenes": [ ... ],
  "post": {
    "content": "<IG/FB/TikTok caption: plain-language hook + 1 line of context + 8-12 hashtags>",
    "youtube_title": "<max 90 chars, curiosity hook + name, ends with #Shorts>",
    "youtube_description": "<2-3 plain sentences + 3-5 hashtags>",
    "youtube_tags": ["<5-10 short tags>"],
    "linkedin_caption": "<professional tone, 3-5 short lines: the innovation, why it still matters for business/tech today, a question to the reader, max 3 hashtags>"
  }
}";

const user = [
  'INNOVATOR ROW: ' + JSON.stringify({name: row.name, country: row.country, era: row.era, invention: row.invention}),
  '',
  'SOURCE TEXT (the ONLY facts you may use):',
  source.slice(0, 14000)
].join('
');

return [{ json: { brain_body: {
  model: 'openai/gpt-4o',
  temperature: 0.7,
  response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: SYSTEM }, { role: 'user', content: user } ]
} } }];

// Parse + validate the Brain output, then build the GitHub dispatch body.
let raw = $json.choices?.[0]?.message?.content || '';
raw = raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let p;
try { p = JSON.parse(raw); } catch (e) { throw new Error('Brain did not return valid JSON: ' + raw.slice(0, 300)); }

const TYPES = ['hook','globe','counter','iconGrid','machine','legacy','outro'];
const ICONS = ['gear','clock','drum','engine','robot','book','drop','bulb'];
if (!Array.isArray(p.scenes) || p.scenes.length < 5) throw new Error('Brain returned too few scenes');
if (p.scenes[0].type !== 'hook' || p.scenes[p.scenes.length - 1].type !== 'outro') throw new Error('First scene must be hook, last must be outro');
for (const s of p.scenes) {
  if (!TYPES.includes(s.type)) throw new Error('Unknown scene type: ' + s.type);
  if (!s.narration) throw new Error('Scene missing narration: ' + s.type);
  s.durationSec = Number(s.durationSec) || 5;
  if (s.type === 'iconGrid' && !ICONS.includes(s.icon)) s.icon = 'gear';
  if (s.type === 'legacy') (s.items || []).forEach(it => { if (!ICONS.includes(it.icon)) it.icon = 'gear'; });
  if (s.type === 'machine') s.steps = (s.steps || []).slice(0, 4);
}

// Fixed brand + posting targets (never trust the model with these)
p.brand = { name: 'T&I NEWS', url: 'tai.news', bg: '#0A1630', accent: '#D4A63A', text: '#F4E9D0' };
p.sfx = true;
const b = p.post || {};
const outro = p.scenes[p.scenes.length - 1];
let ytTitle = (b.youtube_title || (outro.name + ': ' + p.scenes[0].headline + ' ' + p.scenes[0].highlight)).trim();
if (ytTitle.length > 100) ytTitle = ytTitle.slice(0, 97) + '...';   // YouTube title limit is 100 characters
p.post = {
  content: b.content,
  // Facebook 7748, Instagram 7752, TikTok 7908, YouTube 7751, LinkedIn 9116. Add 7747 (X) once the X caption is set up.
  account_ids: [7748, 7752, 7908, 7751, 9116],
  publish_now: true,
  platform_content: {
    youtube: {
      title: ytTitle,
      description: b.youtube_description || b.content,
      privacy: 'public',
      made_for_kids: false,
      is_short: true,
      tags: Array.isArray(b.youtube_tags) ? b.youtube_tags.slice(0, 15) : []
    },
    linkedin: { content: b.linkedin_caption || b.content }
  }
};
if (!p.post.content) throw new Error('Brain returned no post.content caption');
delete p.captions;

return [{ json: {
  props: p,
  // Built-in TEST row never posts (render only). Real Sheet rows post.
  dispatch_body: { ref: 'main', inputs: { props: JSON.stringify(p), post: $('Pick Innovator').first().json._test ? 'false' : 'true', voice: 'am_michael' } }
} }];
